<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js" integrity="sha384-6B1Y+9X6+1wB4wH+0vL8nXb3P2wV8r2z1J8K6pA8g8p4v4aQ5q2r0q6J3cE6q5Y" crossorigin="anonymous"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&display=swap');

        body {
            margin: 0;
            padding: 0;
            font-family: 'Times New Roman', serif;
            font-size: 12pt;
            line-height: 1.4;
            color: #000;
            background: #fff;
        }

        .container {
            max-width: 800px;
            margin: 40px auto;
            padding: 20px;
            border: 1px solid #000;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }

        .header {
            text-align: center;
            margin-bottom: 20px;
        }

        .title {
            font-size: 18pt;
            font-weight: bold;
            margin-bottom: 10px;
        }

        .subtitle {
            font-size: 14pt;
            margin-bottom: 30px;
        }

        .section {
            margin-bottom: 15px;
        }

        .section h2 {
            font-size: 14pt;
            font-weight: bold;
            margin-bottom: 8px;
            border-bottom: 1px solid #000;
            padding-bottom: 4px;
        }

        .text-block {
            margin-bottom: 12px;
            text-align: justify;
        }

        .indent {
            text-indent: 1.5em;
        }

        .placeholder {
            width: 100%;
            height: 200px;
            background: #f0f0f0;
            border: 1px dashed #999;
            margin: 10px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11pt;
            color: #666;
            text-align: center;
        }

        .placeholder img {
            max-width: 100%;
            max-height: 100%;
        }

        .centered {
            text-align: center;
        }

        .right-aligned {
            text-align: right;
        }

        ul, ol {
            margin-left: 2em;
            margin-bottom: 10px;
        }

        li {
            margin-bottom: 5px;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 10px 0;
        }

        th, td {
            border: 1px solid #000;
            padding: 5px;
        }

        th {
            background: #f0f0f0;
            text-align: center;
        }

        .signature {
            margin-top: 30px;
            text-align: center;
            font-style: italic;
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- Document Header -->
        <div class="header">
            <div class="title">[Title: Document Title Here]</div>
            <div class="subtitle">[Subtitle: Subtitle or Document Type]</div>
            <div style="margin-bottom: 20px;">
                [Placeholder for Logo or Header Image]<br>
                <div class="placeholder" style="width: 150px; height: 80px; margin: 0 auto;">[Logo/Image: Placeholder]</div>
            </div>
        </div>

        <!-- Main Content Block 1 -->
        <div class="text-block">
            <p><strong>Document Title</strong><br>
            This is the first paragraph of the main body text. It may span multiple lines and demonstrates proper justification.</p>
        </div>

        <!-- Section with Heading -->
        <div class="section">
            <h2>Section Heading 1</h2>
            <p class="indent">This is the content under the first section heading. The text is indented as per standard document formatting to create visual hierarchy and spacing.</p>
            <p>This additional paragraph continues the section. It shows how multi-paragraph sections are typically rendered in a printed document.</p>
        </div>

        <!-- Placeholder for Image or Diagram -->
        <div class="section">
            <h2>Image Placeholder</h2>
            <div class="centered">
                <div class="placeholder" style="width: 400px; height: 250px; margin: 15px auto;">
                    [Image/Diagram: Placeholder for diagram or photograph]
                </div>
            </div>
            <p class="centered" style="font-size: 10pt; color: #666;">[Caption: Figure 1. Descriptive caption text for the image placeholder]</p>
        </div>

        <!-- Two-column layout simulation using grid -->
        <div class="section">
            <h2>Two-Column Content</h2>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 30px;">
                <div>
                    <p class="indent">Left column text. This demonstrates how side-by-side text blocks are arranged in the original document layout.</p>
                    <p>This is the second paragraph in the left column.</p>
                </div>
                <div>
                    <p class="indent">Right column text. The right column appears immediately next to the left one with balanced spacing.</p>
                    <p>This is the second paragraph in the right column, showing mirror alignment.</p>
                </div>
            </div>
        </div>

        <!-- Bulleted List -->
        <div class="section">
            <h2>Key Points</h2>
            <ul>
                <li>First item in the list. Lists are rendered with proper indentation and bullet markers.</li>
                <li>Second item in the list. The list items are vertically stacked with consistent spacing.</li>
                <li>Third item in the list. This demonstrates how bullet points maintain alignment in the document.</li>
            </ul>
        </div>

        <!-- Numbered List -->
        <div class="section">
            <h2>Steps</h2>
            <ol>
                <li>Step one. Numbered lists are used for sequential instructions.</li>
                <li>Step two. Each item is indented under the previous.</li>
                <li>Step three. Final step in the sequence.</li>
            </ol>
        </div>

        <!-- Table -->
        <div class="section">
            <h2>Table Data</h2>
            <table>
                <tr>
                    <th>Header 1</th>
                    <th>Header 2</th>
                    <th>Header 3</th>
                </tr>
                <tr>
                    <td>Cell A1</td>
                    <td>Cell B1</td>
                    <td>Cell C1</td>
                </tr>
                <tr>
                    <td>Cell A2</td>
                    <td>Cell B2</td>
                    <td>Cell C2</td>
                </tr>
                <tr>
                    <td>Cell A3</td>
                    <td>Cell B3</td>
                    <td>Cell C3</td>
                </tr>
            </table>
        </div>

        <!-- Right-aligned text block -->
        <div class="section">
            <p class="right-aligned">This paragraph is right-aligned to match the document's right margin alignment.</p>
            <p class="right-aligned">Additional right-aligned content continues on the next line.</p>
        </div>

        <!-- Signature Block -->
        <div class="signature">
            _________________________<br>
            [Name: Placeholder for signature]<br>
            <small>Date: [Date Here]</small>
        </div>

        <!-- Footer -->
        <div style="margin-top: 40px; text-align: center; font-size: 10pt; border-top: 1px solid #000; padding-top: 10px;">
            [Footer Text: Page X of Y or Document Footer]
        </div>
    </div>

    <script>
        // MathJax configuration for any LaTeX content if present
        MathJax = {
            tex: {
                inlineMath: [['$', '$'], ['\\(', '\\)']],
                displayMath: [['$$', '$$'], ['\\[', '\\]']],
                processEscapes: true
            }
        };
    </script>
</body>
</html>
